    *(void **)&p_tg_job_cancel = teigeodata_sym(lib, "tg_job_cancel");
    *(void **)&p_tg_job_result = teigeodata_sym(lib, "tg_job_result");
    if (p_tg_bytes_free == NULL || p_tg_last_error == NULL || p_tg_version == NULL) {
        return strdup("not a teigeodata library: tg_version, tg_bytes_free or tg_last_error is missing");
    }
